(function(root,factory){if(typeof module!=='undefined')module.exports=factory;else root.ClinicCustomerCenter=factory;})(typeof window!=='undefined'?window:this,function(){
 const faq=[['예약·내원','진료시간은 어떻게 되나요?','평일은 오전 9시부터 오후 6시까지, 토요일은 오전 9시부터 오후 1시까지 진료합니다. 점심시간은 오후 1시부터 2시까지이며 일요일과 공휴일은 휴진입니다.'],['예약·내원','오늘 방문하고 싶은데 예약이 필요한가요?','당일 진료와 접수 가능 여부는 051-325-1919로 확인해 주세요. 진료 상황과 검사 종류에 따라 대기시간이 달라질 수 있습니다.'],['예약·내원','병원은 어디에 있나요?','부산 사상구 가야대로 276 엠스퀘어메디컬센터 9층입니다. 부산 지하철 2호선 주례역 5번 출구 앞, 주례농협 옆에 있습니다.'],['검사 안내','검사하러 갈 때 무엇을 가져가면 되나요?','신분증과 사용 중인 안경, 복용약 정보, 이전 검사 자료가 있다면 준비해 주세요. 검사별 준비사항은 방문 전 전화로 안내받으실 수 있습니다.'],['진료 상담','수술 비용이나 치료 방법을 온라인으로 알 수 있나요?','일반적인 안내는 가능하지만, 정확한 치료 방법과 비용은 검사 결과에 따라 달라집니다. 현재 눈 상태를 확인한 뒤 의료진과 상담해 주세요.'],['질문 안내','질문을 남기면 어떻게 답변을 받나요?','질문을 비밀글로 등록하면 관리자가 답변합니다. 게시판에서 본인 글을 선택한 뒤 작성할 때 설정한 비밀번호를 입력해 답변을 확인할 수 있습니다.']];
 return `<section class="support-content wrap"><nav class="support-tabs" aria-label="고객센터 메뉴"><a href="#question-board">질문게시판</a><a href="#write-question">질문하기</a><a href="#support-faq">자주 묻는 질문</a></nav><section id="question-board" class="support-section"><div class="support-heading"><h2>비밀 상담 게시판</h2><a class="support-button" href="#write-question">글쓰기 ↗</a></div><p class="support-lead">등록한 질문과 답변은 작성 시 설정한 비밀번호로 확인할 수 있습니다.</p><div id="private-question-list" aria-live="polite"><p>질문 목록을 불러오는 중입니다.</p></div></section><section id="write-question" class="support-section support-write"><div class="support-heading"><div><p class="eyebrow">ASK US</p><h2>질문하기</h2></div><a class="support-phone" href="tel:0513251919">전화 문의 051-325-1919</a></div><p class="support-lead">진료와 내원에 관해 궁금한 내용을 적어주세요.</p><form id="support-question-form"><div class="support-form-grid"><label>문의 분야<select name="topic" required><option value="">선택해 주세요</option><option>예약·내원</option><option>노안·백내장·인공수정체</option><option>망막·녹내장</option><option>소아안과·드림렌즈</option><option>안구건조증·안성형·검진</option><option>기타 문의</option></select></label><label>성함<input name="name" autocomplete="name" maxlength="30" required placeholder="성함을 입력해 주세요"></label><label>비밀번호<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="8자 이상 입력해 주세요"></label><label>비밀번호 확인<input name="passwordConfirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="비밀번호를 다시 입력해 주세요"></label><label class="support-field-wide">제목<input name="subject" maxlength="100" required placeholder="문의 제목을 입력해 주세요"></label><label class="support-field-wide">문의 내용<textarea name="message" rows="6" minlength="10" maxlength="3000" required placeholder="궁금한 내용을 10자 이상 입력해 주세요. 주민등록번호 등 민감한 개인정보는 적지 마세요."></textarea></label></div><label class="support-consent"><input type="checkbox" name="consent" required> 비밀 상담을 위한 이름·문의 내용 수집 및 이용에 동의합니다.</label><p class="support-delivery-note">수집 목적: 문의 접수 및 답변. 보유 기간: 답변 완료 후 1년. 삭제 요청: 051-325-1919. 동의를 거부할 수 있으나 게시판 접수는 제한됩니다. 비밀번호는 글 확인에 필요하며, 주민등록번호 등 민감한 정보는 적지 마세요.</p><div class="support-form-actions"><button class="support-button" type="submit" disabled>비밀글 등록하기 ↗</button></div><p id="support-form-status" role="status" aria-live="polite"></p></form></section><section id="support-faq" class="support-section"><div class="support-heading"><div><p class="eyebrow">FAQ</p><h2>자주 묻는 질문</h2></div></div><div class="support-faq-filters" role="group" aria-label="FAQ 분류">${['전체','예약·내원','검사 안내','진료 상담','질문 안내'].map((c,i)=>`<button type="button" data-faq-filter="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><div>${faq.map(([c,q,a])=>`<details class="support-faq-item" data-faq-category="${c}"><summary><span>Q</span>${q}<b aria-hidden="true">+</b></summary><div><span>A</span><p>${a}</p></div></details>`).join('')}</div></section></section>`;
});
